import{c as r,S as e,j as i,m as l}from"./chunks/framework.8aa1YH_s.js";const f=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 13: Kelime Türleri - Sıfatlar (Ön Adlar)","description":"","frontmatter":{},"headers":[],"relativePath":"13 Kelime Türleri - Sıfatlar (Ön Adlar).md","filePath":"13 Kelime Türleri - Sıfatlar (Ön Adlar).md"}'),t={name:"13 Kelime Türleri - Sıfatlar (Ön Adlar).md"};function n(s,a,m,o,d,g){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="turk-dil-bilgisi-serisi-13-kelime-turleri-sıfatlar-on-adlar" tabindex="-1">Türk Dil Bilgisi Serisi - 13: Kelime Türleri - Sıfatlar (Ön Adlar) <a class="header-anchor" href="#turk-dil-bilgisi-serisi-13-kelime-turleri-sıfatlar-on-adlar" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 13: Kelime Türleri - Sıfatlar (Ön Adlar)”">​</a></h1><p>Kelime türleri yolculuğumuzda isimleri ve isim tamlamalarını geride bıraktık. Bu yazımızda, isimlerin adeta kıyafeti ve süsü olan, onları renk, şekil, durum veya sayı yönünden tamamlayan <strong>Sıfatlar (Ön Adlar)</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre sıfatlar, tek başlarına bağımsız birer nesneyi temsil etmezler. Ancak bir ismin önüne geldiklerinde o isme ait bir özelliği, sınırı veya miktarı göstererek anlam kazanırlar. Türkçede sıfatlar her zaman nitelik veya belirtim yapacakları <strong>ismin solunda (önünde)</strong> yer alır.</p><p>Muharrem Ergin sistematiğinde sıfatlar <strong>iki ana gruba</strong> ayrılır:</p><hr><h2 id="_1-niteleme-sıfatları" tabindex="-1">1. Niteleme Sıfatları <a class="header-anchor" href="#_1-niteleme-sıfatları" aria-label="Permalink to “1. Niteleme Sıfatları”">​</a></h2><p>İsimlerin bünyesinde var olan, onların kalıcı veya geçici özelliklerini; renklerini, şekillerini, durumlarını bildiren sıfatlardır. İsme sorulan <strong>&quot;Nasıl?&quot;</strong> sorusunun cevabıdırlar.</p><ul><li><em>Örnekler:</em><ul><li><strong>Mavi</strong> gökyüzü (<em>Nasıl gökyüzü?</em>)</li><li><strong>Yırtık</strong> kitap (<em>Nasıl kitap?</em>)</li><li><strong>Çalışkan</strong> yazılımcı (<em>Nasıl yazılımcı?</em>)</li><li><strong>Yuvarlak</strong> masa (<em>Nasıl masa?</em>)</li></ul></li></ul><blockquote><p><strong>⚠️ Önemli Not (Unvan Sıfatları):</strong> &gt; Kişilerin meslek, makam, rütbe veya sosyal statülerini bildiren kelimeler de Muharrem Ergin sistematiğinde niteleme sıfatı veya sıfat benzeri unsurlar olarak kabul edilir. Diğer sıfatlardan farklı olarak ismin önünde de sonunda da yer alabilirler: * <strong>Müdür</strong> Mehmet Bey, Ahmet <strong>Kaptan</strong>, <strong>Profesör</strong> Muharrem Ergin.</p></blockquote><hr><h2 id="_2-belirtme-sıfatları" tabindex="-1">2. Belirtme Sıfatları <a class="header-anchor" href="#_2-belirtme-sıfatları" aria-label="Permalink to “2. Belirtme Sıfatları”">​</a></h2><p>İsimleri geçici olarak işaret eden, sayısal olarak ölçen, sınırlayan veya soru yoluyla tamlayan sıfatlardır. Varlıkların kendi özelliklerini değil, dış dünyadaki konumlarını ve miktarlarını bildirirler.</p><p>Muharrem Ergin sistematiğinde belirtme sıfatları <strong>4 alt gruba</strong> ayrılır:</p><h3 id="a-isaret-gosterme-sıfatları" tabindex="-1">A) İşaret (Gösterme) Sıfatları <a class="header-anchor" href="#a-isaret-gosterme-sıfatları" aria-label="Permalink to “A) İşaret (Gösterme) Sıfatları”">​</a></h3><p>İsimleri işaret yoluyla belirten, yerlerini gösteren sıfatlardır.</p><ul><li><strong>Bu, şu, o, beri, öte, karşı...</strong></li><li><em>Örnekler:</em> <strong>Bu</strong> bilgisayar, <strong>şu</strong> sokak, <strong>o</strong> ev, <strong>öte</strong> mahalle.</li></ul><h3 id="b-sayı-sıfatları" tabindex="-1">B) Sayı Sıfatları <a class="header-anchor" href="#b-sayı-sıfatları" aria-label="Permalink to “B) Sayı Sıfatları”">​</a></h3><p>İsimlerin miktarını, sırasını, parçalarını veya paylaşım oranlarını sayısal olarak bildiren sıfatlardır. Kendi içinde 4&#39;e ayrılır:</p><ol><li><strong>Asıl Sayı Sıfatı:</strong> İsimlerin net miktarını bildirir (<em>Kaç?</em>). <ul><li>Örn: <strong>Üç</strong> kitap, <strong>yüz</strong> lira.</li></ul></li><li><strong>Sıra Sayı Sıfatı:</strong> İsimlerin bir dizilişteki derecesini bildirir (<em>Kaçıncı?</em>). <ul><li>Örn: <strong>Birinci</strong> sınıf, <strong>beşinci</strong> kat.</li></ul></li><li><strong>Üleştirme Sayı Sıfatı:</strong> Paylaştırma anlamı taşır (<em>Kaçar?</em>). <ul><li>Örn: <strong>İkişer</strong> dilim, <strong>yüzer</strong> sayfa.</li></ul></li><li><strong>Kesir Sayı Sıfatı:</strong> Parça-bütün ilişkisini gösterir (<em>Kaçta kaç?</em>). <ul><li>Örn: <strong>Yarım</strong> ekmek, <strong>%50</strong> kar, <strong>çeyrek</strong> altın.</li></ul></li></ol><h3 id="c-belgisiz-sıfatlar" tabindex="-1">C) Belgisiz Sıfatlar <a class="header-anchor" href="#c-belgisiz-sıfatlar" aria-label="Permalink to “C) Belgisiz Sıfatlar”">​</a></h3><p>İsimleri tam olarak değil, aşağı yukarı, belli belirsiz bir şekilde nicelik veya nitelik yönünden belirten sıfatlardır. Kesinlik bildirmezler.</p><ul><li><strong>Bazı, birkaç, birçok, her, hiçbir, kimi, birtakım, tüm...</strong></li><li><em>Örnekler:</em> <strong>Bazı</strong> günler, <strong>birkaç</strong> kişi, <strong>her</strong> sabah, <strong>hiçbir</strong> emek.</li></ul><h3 id="d-soru-sıfatları" tabindex="-1">D) Soru Sıfatları <a class="header-anchor" href="#d-soru-sıfatları" aria-label="Permalink to “D) Soru Sıfatları”">​</a></h3><p>İsimlerin niteliğini, miktarını veya yerini soru yoluyla öğrenmeyi amaçlayan sıfatlardır. Cevapları da yine bir sıfattır.</p><ul><li><strong>Nasıl, kaç, kaçıncı, hangi, ne kadar...</strong></li><li><em>Örnekler:</em> <strong>Hangi</strong> takım? (<em>Beşiktaş</em>), <strong>Kaçıncı</strong> sayfa? (<em>Yüzüncü sayfa</em>), <strong>Nasıl</strong> bir ev? (<em>Güzel bir ev</em>).</li></ul><hr><h2 id="_3-sıfat-tamlaması-ve-adlasmıs-sıfat" tabindex="-1">3. Sıfat Tamlaması ve Adlaşmış Sıfat <a class="header-anchor" href="#_3-sıfat-tamlaması-ve-adlasmıs-sıfat" aria-label="Permalink to “3. Sıfat Tamlaması ve Adlaşmış Sıfat”">​</a></h2><h3 id="sıfat-tamlaması" tabindex="-1">Sıfat Tamlaması <a class="header-anchor" href="#sıfat-tamlaması" aria-label="Permalink to “Sıfat Tamlaması”">​</a></h3><p>Bir sıfatın bir ismin önüne gelerek oluşturduğu kelime grubuna <strong>Sıfat Tamlaması</strong> denir. İsim tamlamalarının aksine sıfat tamlamalarında <strong>asla tamlayan veya tamlanan eki bulunmaz</strong>.</p><ul><li><em>Örnek:</em> <strong>Temiz</strong> kod, <strong>eski</strong> defterler.</li></ul><h3 id="adlasmıs-sıfat" tabindex="-1">Adlaşmış Sıfat <a class="header-anchor" href="#adlasmıs-sıfat" aria-label="Permalink to “Adlaşmış Sıfat”">​</a></h3><p>Bir sıfat tamlamasında, sıfattan sonra gelen isim düşerse ve isimdeki ekler sıfata geçerse, o sıfat artık tek başına bir isim gibi davranmaya başlar. Buna <strong>Adlaşmış Sıfat</strong> denir.</p><ul><li><em>Örnek:</em> <strong>İhtiyar insanlar</strong> yavaş yürür. (Sıfat tamlaması)</li><li><em>Adlaşmış Hali:</em> <strong>İhtiyarlar</strong> yavaş yürür. (Sıfat, ismin yerine geçerek adlaşmıştır).</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in tasnifiyle sıfatlar, Türkçenin nesneleri tasvir etme ve dünyayı kategorize etme gücünü temsil eder. Sıfatların isimlerin önünde eksiz bir şekilde durması, dile müthiş bir çeviklik kazandırır. Bir sıfatı isimden ayıran en büyük sınır, sıfatın arkasındaki isme olan mutlak sadakatidir; o isim gittiği anda sıfat ya adlaşır ya da düşer.</p><p>Sıfatlar dosyasını da başarıyla rafa kaldırdık aslanım!</p><p>Serimizin 14. bölümünde, isimlerin yerini gizlice tutan, dile pratiklik ve esneklik katan çok önemli bir türe geçiyoruz: <strong>&quot;Zamirler (Adıllar)&quot;</strong>.</p><p>Yola devam, komutunu bekliyorum!</p>',39)])])}const u=r(t,[["render",n]]);export{f as __pageData,u as default};
